69	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
70	    return total;
71	  }, 0);
72	
73	  return {
74	    metadata: {
75	      generatedAt,
76	      outputsPath,
77	      referencesPath,
78	      totalSamples
79	    },
80	    metrics: evaluations
